"""report.md writer, called by run.py with the results dict (so every number in the report is regenerated)."""

import math
LSB = 3.3/4096


def write(d):
    c = d["cases"]
    design = [x for x in c if "[" not in x["id"] or x["id"].startswith(("P3-a [OPA", "P3-b [OPA", "P3-c [OPA")) or x["id"] in ("C3-t [+-1.25 V, 256 points]", "C3-t [+-5 V, 1024 points]") or x["id"].startswith(("C1-p [", "C1-q [")) or x["id"] == "C4-d [2 x 100 nF at REFP0]"]
    variant = [x for x in c if x not in design]
    nf = [x for x in c if not x["ok"]]
    nfd = [x for x in design if not x["ok"]]; nfv = [x for x in variant if not x["ok"]]
    L = []
    A = L.append
    A("# AFE steps 2a (power) and 2e (calibration, Phase 3): simulation report\n")
    A("Regenerated by `python3 -I run.py` in this folder (numpy + ngspice only; at most 3 ngspice processes at a time, `POWERCAL_JOBS`, and the results do not depend on that number). Every number below is computed or simulated by that script, or quoted with its datasheet section; `results.json` is the raw output, `netlists/` the ngspice decks it ran, `logs/` and `raw/` the ngspice output. Mutation tests of the checks: section 9 (`run.py` runs them every time).\n")
    A("## 1. Report header (afe-plan: versions, model hashes, stimuli)\n")
    A(f"- ngspice: `{d['tools']['ngspice']}`; python {d['tools']['python']}, numpy {d['tools']['numpy']}. KiCad: not used by this step (no schematic exists yet; netlists are hand-written ngspice).")
    A("- Date 2026-11-11. Requirements: `docs/afe.md` as merged on 2026-11-11 (SC-9 now also covers the AWG's coupling into a scope channel while DAC0 plays, including through the off injection switch; PW-7 start-up about 15 s; SC-3 about 20-30 kohm input). Design state: the scope stage RF 953 / RG 249 returned to Vmid, Rnp 680, Riso 22 (`sim/scope`); **the scope's 1 Mohm divider (R1 = R3 = 330k + 330k + 100k, R2 = 330k, no trimmer) is final again: SM-5 is dropped (owner, 2026-11-11), with the ~20-30 kohm input it would have needed, and PR-1/PR-3 are +-12 V on both inputs at once**; AWG variant n1 (Ra (4.7k||4.7k) + 3 x 4.7k, Rb 4 x 4.7k, Rx 330k, Rf 249 + 49.9, Rg 249, 22||22 ohm supply filter); approved 2026-11-11: no ferrite bead (R2), 249 ohm sense filter (M-3), Vmid divider 2 x 330k 0.1 % (M-7) with 10 uF at the tap (M-10); DAC8551 removed (PA-3 injects DAC0 through the TMUX1119).")
    A("- Vendor models are used only by relative path from `hardware/afe-proto/models/` and are never copied: TI OPA365 (`opa365/OPA365_PSPICE.lib`) and OPA354 (`opa354/OPA354_PSPICE.lib`). Everything else is OUR open behavioural subcircuit in `models/` (CC-BY-SA 4.0, `models/LICENSE`), each parameter annotated with its datasheet section; TI's LM27762, TMUX1119 and REF3030 models do not parse in ngspice 47 (`models/SOURCES.md`) and are not used.")
    A("\n| file | sha256 (checked against `models/SOURCES.md` on every run; the run aborts on a mismatch) | matches |\n|---|---|---|")
    for k, v in d["hashes"].items():
        A(f"| {k} | `{v['sha256']}` | {'yes' if v['matches_SOURCES_md'] else 'NO'} |")
    A("\n**Stimuli.** Supply: Due 5V pin 4.4 and 5.25 V (3.4-5.3 V in the sweep), source resistance 0.2 and 1.0 ohm, ramps 1 us / 100 us / 5 ms, soft-start 20 us / 2 ms, three enable orderings, overshoot 0-0.4 V per rail, rails at their tolerance maxima (LM27762 VFB +-1.5 %, 0.1 % divider). Loads: scope op-amps 5/6.3 mA, AWG short 23 mA (step 0 -> 23 mA in 100 ns), PR-4 +-5 V on the AWG output. Ripple: LM27762 5 mV peak at 1.7/2.0/2.3 MHz and harmonics 1/n to 10 MHz, assumed LM2734Y 10 mV peak at 3 MHz. Unpowered: the Due's 5V and 3.3 V pins held at 0 V (a short: the maximum possible current into them), +-12 V on both scope inputs at once through R1 (PR-1/PR-3), +-5 V on the AWG output. Vmid: full-scale input on one channel (its RG current into the shared node), 1 kHz-10 MHz, and a 10 ns current step. Calibration: Monte Carlo 4000-15000 draws per row, seed fixed.\n")
    A("## 2. Result in one paragraph\n")
    A(f"{len(c)} cases, {len(c)-len(nf)} pass, {len(nf)} fail. Of these, {len(design)} describe the design as it stands ({len(design)-len(nfd)} pass; fails: " + ("; ".join(x["id"] for x in nfd) or "none") + f") and {len(variant)} are comparisons, previous arrangements and options, tagged `[...]` ({len(variant)-len(nfv)} pass; fails: " + ("; ".join(x["id"] for x in nfv) or "none") + "). No limit was relaxed to pass a case. Approved and now the design (2026-11-11): one Vmid buffer per scope channel plus one for the AWG's Rg (SC-9 through Vmid passes, P8-a / P8-f), the 45 kohm negative-rail divider, the buffered-DAC0 AWG, **the ADS124S08 as the precision ADC** and **the BNC-tee calibration** with one TMUX1119 ratio switch on the AWG-sense divider (k = 1/2), 100k from the AWG's Vmid to S1, and 2 x 100 nF at REFP0. The injection T-switches and their C3 rows are retired. The C1-p rows marked as PR-4's +-5 V band are recorded and not judged (PR-4 allows shield damage there).\n")
    A("## 3. Pass/fail table\n")
    A("| case | requirement | limit | worst-case result | margin | |\n|---|---|---|---|---|---|")
    for x in c:
        A(f"| {x['id']} | {x['req']} | {x['limit']} | {x['worst']}{(' - ' + x['note']) if x['note'] else ''} | {x['margin']} | **{'PASS' if x['ok'] else 'FAIL'}** |")
    A("")
    A("## 4. Recommended design (what the numbers above are for)\n")
    r = d["rails"]
    c15 = d["c15850"]
    A(f"**5 V feed (R2, approved).** Due 5V pin -> 1 ohm 1 % 0603 sense resistor (test point either side, D7) -> **2 x 10 uF X5R 0805 25 V, Samsung CL21A106KAYNNNE, LCSC C15850** -> LM27762DSSR (LCSC C473398, Extended). **No ferrite bead**: the sense resistor and the bulk are the feed's filter, and each scope op-amp branch has a 1 ohm ahead of its 10 uF. **Every 10 uF is now modelled from Samsung's characterisation of the part** (its product page's embedded data, stored and hashed in `models/cl21a106kaynnne/`): ESR {c15['esr_mohm']['2 MHz']:.1f} mohm at 2 MHz and {min(v for k, v in c15['esr_mohm'].items() if float(k.split()[0]) >= 4):.1f}-{max(v for k, v in c15['esr_mohm'].items() if float(k.split()[0]) >= 4):.1f} mohm at 4-10 MHz, ESL {c15['esl_nH']:.2f} nH fitted from |Z| over 3-10 MHz (self-resonance {c15['srf_MHz']:.2f} MHz), capacitance {c15['dc_bias_pct']['5.0 V']:.0f} % at 5 V, {c15['dc_bias_pct']['3.3 V']:.0f} % at 3.3 V, {c15['dc_bias_pct']['2.07 V']:.0f} % at 2.07 V and {c15['dc_bias_pct']['1.65 V']:.0f} % at 1.65 V of DC bias, with -10 % tolerance on top. The ESR is Samsung's 0 V, 25 C curve; its change with bias is not given *(check)*. **No series element (Schottky, PFET, ideal diode) in the 5 V feed.**")
    A(f"**Rails.** EN+ and EN- tied to VIN. +3.3 V_A: 174 k / 100 k 0.1 % -> {r['vp_nom']:.3f} V nominal, {r['vp_min']:.3f}-{r['vp_max']:.3f} V. Negative rail (approved 2026-11-11; the 768k has left the BOM): **R3 = 330 k || 100 k, R4 = 330 k || 330 k || 330 k** 0.1 % -> -{r['vn_nom']:.4f} V nominal, -{r['vn_min']:.3f} to -{r['vn_max']:.3f} V, 45 kohm at FB- (the FB- input current is not in the datasheet *(check)*). Bare rails at the maxima {r['sum_max']:.3f} V DC, {5.5-r['sum_max']:.3f} V under OPA365's 5.5 V; start-up {d['p1_worst_pins_nosch']:.3f} V on the bare rails and {d['p1_worst_pins_sch']:.3f} V at the AWG op-amp pins (P1-a); overshoot tolerated {d['p1_allowed_overshoot']['sch']*1e3:.0f} mV per rail with the Schottkys, {d['p1_allowed_overshoot']['nosch']*1e3:.0f} mV without (P1-b, model gap G1).")
    A("**AWG (buffered DAC0, 2026-11-11; sim/loop step buf, being verified in sim/awg).** DAC0 -> 680 ohm -> OPA365 follower (330k to Vmid at its input, its own Schottky and 100 nF from +3.3 V_A) -> Ra 953 -> V+, Rb 953 + 249||249 + 22 to ground; Rg 953 to the AWG's own Vmid buffer, Rf 953 + 249||249 + 22 with 12 pF. Its supply pins: 10 uF at the rail, 22 || 22 ohm, 100 nF, then the series BAT54-class Schottky; P1, P2, P4 and P7 model that. The static shift at the op-amp pins with a 23 mA short is %.0f mV (P2-a); the LDO ripple at the AWG output, now also through the DAC0 buffer's supply, is %.2f uV rms against the 20 uV internal share of AW-6 (P4-b; raised from 10 uV, accepted 2026-11-11)." % (
        max(v["shift_p"] for k, v in d["p2"].items() if k != "shutdown")*1e3, d["p4"]["residue_rms"]["awg"]["total"]*1e6))

    A("**+3.3 V_A bleed:** one 4.7 kohm 1 %% 0603 resistor to ground (UNI-ROYAL 0603WAF4701T5E, LCSC C23162; Basic *(check)*). It is the only bleed on that net; it costs %.2f mA (P3 items). **Scope op-amp rail filtering (not a signal band limit, SC-5):** per op-amp group a ferrite bead (C1002) + 10 uF to the rail, 100 nF at the pins; scope op-amps V- = GND." % (3.34/4.7e3*1e3))
    lp = d["p8_loops"]; k0 = list(lp)[0]; v0 = lp[k0]
    vl = d["vmid_loop"]; si = d["vmid_standin"]; vx = d["vmid2"]["Vmid x2"]
    A(f"**Vmid (approved 2026-11-11).** 2 x 330 k 0.1 % from the Due 3.3 V pin (M-7, 5 uA), 10 uF at the tap (M-10; {d['p8_startup']['2 x 330k, 10 uF (M-7 + M-10)']['t_half_lsb_s']:.1f} s to 0.5 LSB, PW-7), then one OPA365 follower per scope channel on that tap. The AWG's Rg returns to the AWG's own Vmid (sim/awg variant buf): a 330k / 330k 0.1 % divider off +3.3 V_A with 12 pF at its tap and an OPA365 follower with no output capacitor on its own BAT54S die and 100 nF (5 uA; phase margin 77 deg by the same method, P8-j [other buffers]). Its divider passes +3.3 V_A ripple to the AWG output: P4-b reads {d['p4']['residue_rms']['awg']['total']*1e6:.1f} uV rms against the 20 uV internal share of AW-6 (raised from 10 uV, accepted 2026-11-11). **Both scope channels' buffers in one TLV9062 (C398355; owner, 2026-11-11)**, each half with whatif/lowcost-scope/vmid's loop: isolation 4 x 1R in parallel (0.25 ohm), DC feedback from the node through 4.7k, HF feedback from the buffer output through 1 uF, 6 x 10 uF (C15850) + 100 nF at each node. The buffer in these netlists is the behavioural stand-in fitted there to TI's TLV9062 model (within 0.59 % of its loop impedance; TI's model needs PSpice mode and does not converge beside the OPA354 model in ngspice 47); TI's model gave a 0.252 ohm peak there. Here the impedance peaks at {vl['nominal']['zmax']:.3f} ohm at {vl['nominal']['fz']/1e3:.0f} kHz, worst {vl['worst_z']['zmax']:.3f} ohm over the X7R's +-23.5 %, the 10 uF at Samsung's 1.65 V derating with -10 % or nominal, and its ESR (P8-i, target 0.3); phase margin {vl['nominal']['pm']:.0f} deg, worst {vl['worst_pm']['pm']:.0f} deg (P8-j); the stiffened OPA365 loop it replaces read {vl['extra']['opa_stiff']['zmax']:.3f} ohm and {vl['extra']['opa_stiff']['pm']:.0f} deg. A full-scale step on its own node is {vx['step_own_mV']:.2f} mV with {vx['own_opp_pct']:.0f} % opposite excursion, settled in {vx['own_settle_us']:.0f} us. SC-9 between the channels is {vx['xt']/LSB:.2f} LSB (P8-a, the shared sense node at DC); through the package, 100 dB of channel separation at DC (P8-l). The AWG's own Vmid follower stays an OPA365. **Linear stand-in for the loop agent** (P8-k): the TLV9062 half as A0 / (1 + s A0 / (2 pi GBW)) behind Rout, A0 = {si['A0_dB']:.1f} dB, GBW = {si['GBW_Hz']/1e6:.1f} MHz, Rout = {si['Rout_ohm']:.1f} ohm, fitted to the macromodel loop's |Z|: within {si['err_1k_1M']*100:.2f} % from 1 kHz to 1 MHz and {si['err_100_10M']*100:.2f} % from 100 Hz to 10 MHz, and {max(si['err_other_corners'].values())*100:.1f} % at the other corners; these are fitted values, not datasheet figures.")
    b = d["c1_buffer"]
    A(f"**Reference and ladder (PA-9 / D11, decided 2026-11-11).** REF3030E (3.0 V, 0.1 %) -> **directly, no buffer (B, owner 2026-11-11)** -> **eight discrete 249 ohm 0.1 % 10 ppm/K resistors** (RESI PTFR0603B249RN9, C2692731, a type already in the design): three in parallel at the bottom, five in series above, {b['r_min']/(1-0.001):.0f} ohm, {b['i_nom_mA']:.2f} mA nominal ({b['i_max_mA']:.2f} mA at -tol, the budget figure): taps at 0.188 / 0.750 / 1.312 / 1.875 / 2.438 / 3.000 V on A2..A7, worst tap source {d['c1_zmax']['nominal']:.0f} ohm, the top tap being the REF3030E output itself (= REFP0). It replaces the 330 ohm 5 % arrays (C12018, an Extended part). Tolerance and tempco are read out by the precision ADC at every calibration (C2). No capacitor on the taps. **Precision ADC (2026-11-11): ADS124S08IPBSR** (C2870171, TQFP-32): AVDD and DVDD from +3.3 V_A (AVDD 330 nF minimum, DVDD 100 nF, Sec 11.4), REFP0 = the REF3030E node, REFN0 = AGND, PGA bypassed, single-ended against AINCOM = AGND, low-latency filter at 20 SPS. **Its inputs:** the six ladder taps (the top tap is REFP0's own node), the AWG-sense tap and the sense divider's bottom node; the rest spare. Six taps: C2-a {d['c2']['ladder+MCP only: MCP-calibrated, 6 taps (design)']['p999']:.2f} LSB, one dropped {d['c2']['ladder+MCP only: MCP-calibrated, 5 taps (one of 6 dropped)']['p999']:.2f}, with leakage {d['c2']['ladder+MCP+leakage 0.5 uA: MCP-calibrated, 6 taps']['p999']:.2f} (the internal keys still say MCP; the reading is the ADS124S08's: INL 10 ppm FSR max = 20 ppm of the 3 V span, 1.2 uVrms, input current 1 nA/V typ, no loading correction). With no buffer there is no offset between the top tap and REFP0. **Sequencing rule (B): the Due does not read the ladder while the ADS124S08 converts** (C1-d: a Due sample on the top tap is 0.12 LSB on the reference node before the REF3030E recovers it, and its output impedance at MHz is not modelled). **Calibration (PA-3): the BNC tee**, see section 4b; the injection switches are gone.")
    A("")
    A("## 5. Notes on the power results\n")
    p6 = d["p6_rows"]
    A("**PW-6 sweep, 5V pin, Due 3.3 V = min(3.3, V5 - h) with h = 1.0 / 1.2 V.** The AFE's own rails regulate down to V5 = %.2f V (3.3 V LDO is the limit). P6-a is checked at 4.4 V; afe.md PW-6's minimum is now 4.50 V, so the check is the stricter one. SC-2 itself (AREF >= 3.20 V) is lost below V5 = %.1f V (h = 1.0) or %.1f V (h = 1.2).\n" % (d["p6_min_v5_rails"], d["p6_aref_below_3p20"]["h1.0"], d["p6_aref_below_3p20"]["h1.2"]))
    A("| V5 (V) | AFE Vin (V) | + rail margin (V) | - rail margin (V) | V33, h=1.0 | V33, h=1.2 |\n|---|---|---|---|---|---|")
    for x in p6:
        if x["v5"] in (3.5, 4.0, 4.2, 4.3, 4.4, 4.5, 4.75, 5.0, 5.25):
            A(f"| {x['v5']:.2f} | {x['vin']:.2f} | {x['margin_pos']:.2f} | {x['margin_neg']:.2f} | {x['v33_h1.0']:.2f} | {x['v33_h1.2']:.2f} |")
    u = d["p6_usb"]
    A(f"\n**USB path.** Polyfuse + FDN340P + contacts, assumed 0.5 + 0.1 + 0.05 ohm *(check, no datasheet in the repo)*, at 400 mA: {u['drop']*1e3:.0f} mV, so a 4.75 V host gives V5 = {u['v5_from_4v75']:.2f} V; a bus-powered 4.4 V gives {u['v5_from_4v40']:.2f} V.\n")
    A("**Current (mA, every datasheet maximum at once).**\n")
    A("| variant | normal | AWG shorted | +-5 V on AWG (65 mA ISC) | Due + AFE with the simulated PR-4 increment |\n|---|---|---|---|---|")
    for vname, v in d["p3"].items():
        mx = list(v["max"].values())
        A(f"| {vname} | {mx[0]:.1f} | {mx[1]:.1f} | {mx[2]:.1f} | {300+mx[2]-65+max(d['p7_ext_delta_mA'], 65):.1f} |")
    A("\nItems: " + "; ".join(f"{k} {v:.2f}" for k, v in d["p3_items"].items()) + " (mA, max values, OPA365 scope). The DAC8551 (0.24 mA) is removed. The simulated PR-4 increment is %.1f mA (5 V into 49.9 ohm with the output held near 0).\n" % d["p7_ext_delta_mA"])
    A("**Start-up and ordering (P1).** Peak across the AWG op-amp pins over %d runs: %.3f V with the series Schottkys, %.3f V on the bare rails (5.5 V limit). Hot-plug inrush with a 1 us 5 V edge reaches %.1f A for microseconds.\n" % (len(d["p1_rows"]), d["p1_worst_pins_sch"], d["p1_worst_pins_nosch"], d["p1_inrush_A"]))
    A("**What each rail filter buys and costs (P4).** Stripping the bulk, branch and local capacitors takes the worst amplifier-pin ripple from %.3f mV to %.1f mV peak against PW-2's 20 mV. Residue at the scope pin is %.2f uV rms worst = %.2f %% of SC-6; at the AWG output %.2f uV = %.2f %% of AW-6.\n" % (
        max(v["total"] for v in d["p4"]["pin_ripple_pk"].values())*1e3, d["p4_stripped"]["pin_pk"]*1e3,
        max(v["total"] for k, v in d["p4"]["residue_rms"].items() if k != "awg")*1e6, max(v["total"] for k, v in d["p4"]["residue_rms"].items() if k != "awg")/0.2e-3*100,
        d["p4"]["residue_rms"]["awg"]["total"]*1e6, d["p4"]["residue_rms"]["awg"]["total"]/0.1e-3*100))
    A("**Back-feed (P7), every feed variant, Due 5V and 3.3 V pins held at 0 V.** `iso` = series Schottkys on the AWG op-amp pins. The scope channel now carries R3 to the sense node, so a scope input also reaches the Due's 3.3 V pin (through 100 ohm).\n")
    A("| feed | iso | stimulus | V+ rail (V) | V- rail (V) | into Due 5V pin | into Due 3.3 V pin | AWG V+ pin | AWG V- pin |\n|---|---|---|---|---|---|---|---|---|")
    for x in d["p7"]:
        A(f"| {x['feed']} | {'yes' if x['iso'] else 'no'} | {x['stim']} | {x['vp']:.3f} | {x['vn']:.3f} | {x['i_due']*1e6:.1f} uA | {x['i_d33']*1e6:.2f} uA | {x['awp']:.2f} | {x['awn']:.2f} |")
    A("\nPowered, +-5 V on the AWG output: " + "; ".join(f"{x['stim']}: {x['i_due']*1e3:.0f} mA from the 5V pin" for x in d["p7_powered"]) + ".\n")
    A("## 5b. Notes on the calibration results\n")
    s0 = max(x["err_lsb"] for x in d["c1"] if x["ctap"] == "0"); s1 = max(x["err_lsb"] for x in d["c1"] if x["ctap"] == "100n")
    A(f"**Tap impedance and settling.** Worst tap Thevenin {d['c1_zmax']['nominal']:.0f} ohm at tap {d['c1_zmax']['tap']}, {d['c1_zmax']['all_elements_5pct_high']:.0f} ohm with every element at +tol (SC-10 limit 5 kohm). Settling within the 667 ns window: {s0:.4f} LSB with no tap capacitor (the simulator's floor); with 100 nF at each tap {s1:.3f} LSB. S/H model: Csample 6.0 pF, Ron <= 3.8 kohm, both inferred from tTRACK = 0.054 x Z + 205 ns (Sec 45.7.2.1).\n")
    A("**Fit sensitivity (99.9th percentile of the worst error at the span ends 0.2 V / 3.1 V, 12-bit LSB):**\n")
    A("| row | 50 % | 99 % | 99.9 % | max |\n|---|---|---|---|---|")
    for k, v in d["c2"].items():
        A(f"| {k} | {v['p50']:.3f} | {v['p99']:.3f} | {v['p999']:.3f} | {v['max']:.3f} |")
    A("\nThe Due ADC's own INL (1.2 LSB max) puts a floor of %.2f LSB on any 6-point fit; that is the converter, not the ladder.\n" % d["c2_inl_floor_lsb"])
    A(f"**Ladder current on the REF3030E (design, B).** {b['i_max_mA']:.2f} mA worst (the ladder at -tol plus REFP0's 18 uA), inside the 0-10 mA load-regulation range; load regulation <= {b['loadreg_uV']:.0f} uV (15 ppm/mA, specified at VIN = VOUT + 0.5 V where this board has {b['headroom_V']*1e3:.0f} mV *(check)*); self-heating {b['self_heat_K']:.2f} K = {b['self_heat_ppm']:.1f} ppm. Ratiometric for the ADS124S08, whose REFP0 is the same node; for the Due's gain fit it is a static PA-6 term (C4-b). A series element dissipates {b['p_series_elem_mW']:.2f} mW; its rating was not read *(check)*.\n")
    lv = d["ladder_variants"]
    A("**Ladders compared.** Same arrangement, 3 in parallel at the bottom and 5 in series above, same tap ratios:\n")
    A("All rows: 6 taps.\n")
    A("| ladder | total | worst tap | REF3030E current at -tol | C1-c margin to 10 mA | C2-a | C2-b | C2-c (leakage) | C2-d re-read / stale | AFE shorted, OPA354 |\n|---|---|---|---|---|---|---|---|---|---|")
    A(f"| 249R 0.1 % (design) | {b['r_min']/(1-0.001):.0f} | {d['c1_zmax']['nominal']:.0f} | {b['i_max_mA']:.2f} mA | {b['i_lim_mA']-b['i_max_mA']:.2f} mA | {d['c2']['ladder+MCP only: MCP-calibrated, 6 taps (design)']['p999']:.3f} | {d['c2']['ladder+MCP only: MCP-calibrated, 5 taps (one of 6 dropped)']['p999']:.3f} | {d['c2']['ladder+MCP+leakage 0.5 uA: MCP-calibrated, 6 taps']['p999']:.3f} | {[v for k_, v in d['c2'].items() if k_.startswith('re-read')][0]['p999']:.3f} / {[v for k_, v in d['c2'].items() if k_.startswith('stale')][0]['p999']:.3f} | {list(d['p3']['OPA354 scope']['max'].values())[1]:.1f} |")
    for k, v in lv.items():
        A(f"| {k} | {v['total']:.0f} | {v['zmax']:.0f} | {v['buffer']['i_max_mA']:.2f} mA | {v['buffer']['i_lim_mA']-v['buffer']['i_max_mA']:.2f} mA | {v['c2a']:.3f} | {v['c2b']:.3f} | {v['c2c']:.3f} | {v['c2d_reread']:.3f} / {v['c2d_stale']:.3f} | {v['p3_shorted']['OPA354']:.1f} |")
